import { useState, useEffect, useRef } from "react";
import { useApp } from "../context/AppContext";
import { useMesaj } from "../context/MesajContext";
import { Pill } from "./UI";

export default function ChatSayfasi({ konusmaId, onGeri, isKamyoncu }) {
  const { oturum } = useApp();
  const {
    konusmalar,
    mesajGonder,
    mesajiOkundu,
    tumMesajlariOkundu,
    konusmaBasliginiGuncelle,
    konusmaTemizle
  } = useMesaj();

  const [mesaj, setMesaj] = useState("");
  const [yukleniyor, setYukleniyor] = useState(false);
  const [dosya, setDosya] = useState(null);
  const [konusmaAcildi, setKonusmaAcildi] = useState(false);
  const [konusmaBitti, setKonusmaBitti] = useState(false);
  const messageContainerRef = useRef(null);

  const konusma = konusmalar.find(k => k.id === konusmaId);
  const isBenKamyoncu = oturum?.rol === "kamyoncu";
  const partnerAd = konusma?.partnerAd || "";
  const partnerRol = konusma?.partnerRol || "";
  const baslik = konusma?.baslik || "";
  const okunmamis = konusma?.okunmamis || 0;
  const sonGuncelleme = konusma?.sonGuncelleme || new Date().toISOString();

  // Konuşma açıldığında "konuşma açıldı" mesajını gönder
  useEffect(() => {
    if (konusma && konusma.mesajlar.length === 0) {
      setKonusmaAcildi(true);
      setTimeout(() => {
        setKonusmaAcildi(false);
      }, 3000);
    }
  }, [konusma?.id]);

  useEffect(() => {
    if (konusma) {
      messageContainerRef.current?.scrollTo({ top: messageContainerRef.current.scrollHeight, behavior: "smooth" });
    }
  }, [konusma?.mesajlar.length]);

  useEffect(() => {
    if (okunmamis > 0) {
      tumMesajlariOkundu(konusmaId);
    }
  }, [okunmamis, konusmaId, tumMesajlariOkundu]);

  // Her mesaj eklendiğinde otomatik kaydır
  useEffect(() => {
    if (konusma?.mesajlar.length > 0) {
      messageContainerRef.current?.scrollTo({ top: messageContainerRef.current.scrollHeight, behavior: "smooth" });
    }
  }, [konusma?.mesajlar]);

  if (!konusma) return (
    <div className="scroll-content" style={{ display: "flex", alignItems: "center", justifyContent: "center", minHeight: 400 }}>
      <div style={{ textAlign: "center" }}>
        <button onClick={onGeri} style={{ fontSize: 24, background: "none", border: "none", cursor: "pointer" }}>‹</button>
        <div className="display" style={{ fontSize: 20, marginTop: 16 }}>Konuşma bulunamadı</div>
      </div>
    </div>
  );

  const dosyaYukle = async (e) => {
    const dosya = e.target.files[0];
    if (!dosya) return;

    setYukleniyor(true);
    try {
      const yukluDosya = await mesajGonder.dosyaYukle(dosya);
      await mesajGonder(konusmaId, "", yukluDosya.veriTipi, yukluDosya);
      setMesaj("");
      setDosya(null);
    } catch (err) {
      alert("Dosya yüklenemedi");
    } finally {
      setYukleniyor(false);
    }
  };

  const gonder = async (e) => {
    e.preventDefault();
    if (!mesaj.trim() && !dosya) return;

    await mesajGonder(konusmaId, mesaj, "metin", null);
    setMesaj("");
    setDosya(null);
  };

  const temizle = () => {
    konusmaTemizle(konusmaId);
    setKonusmaBitti(true);
    setTimeout(() => {
      setKonusmaBitti(false);
    }, 2000);
  };

  const ilkMesajiOkundu = konusma.mesajlar.length > 0 && konusma.mesajlar[0].gonderen === "konusmaci";

  return (
    <div className="scroll-content" style={{ display: "flex", flexDirection: "column", height: "calc(100vh - 140px)" }}>
      {/* Header */}
      <div style={{ display: "flex", alignItems: "center", gap: 12, padding: "12px 16px", borderBottom: "1px solid var(--border)", background: konusma.bg || "var(--bg1)" }}>
        <button onClick={onGeri} style={{ fontSize: 24, background: "none", border: "none", cursor: "pointer" }}>‹</button>

        <div style={{ flex: 1, display: "flex", alignItems: "center", gap: 12 }}>
          {konusma.resim ? (
            <img src={konusma.resim} alt="Profil" style={{ width: 40, height: 40, borderRadius: "50%", objectFit: "cover" }} />
          ) : (
            <div style={{ width: 40, height: 40, borderRadius: "50%", background: "var(--bg3)", display: "flex", alignItems: "center", justifyContent: "center", fontSize: 20 }}>
              {partnerRol === "kamyoncu" ? "🚛" : "🏢"}
            </div>
          )}
          <div style={{ flex: 1 }}>
            <div style={{ display: "flex", alignItems: "center", gap: 8 }}>
              <div style={{ fontWeight: 600, fontSize: 16 }}>{partnerAd}</div>
              {partnerRol === "kamyoncu" && (
                <Pill durum="kamyoncu" />
              )}
              {partnerRol === "issiz" && (
                <Pill durum="issiz" />
              )}
            </div>
            {baslik && (
              <div style={{ fontSize: 12, color: "var(--text3)", fontWeight: 500 }}>
                {baslik}
              </div>
            )}
          </div>
        </div>

        {okunmamis > 0 && (
          <div style={{
            display: "flex",
            alignItems: "center",
            gap: 4,
            background: "var(--mavi)",
            color: "#fff",
            padding: "4px 10px",
            borderRadius: "20px",
            fontSize: 11,
            fontWeight: 600
          }}>
            <span>{okunmamis}</span>
            <span>Yeni</span>
          </div>
        )}

        <div style={{ fontSize: 11, color: "var(--text3)" }}>
          {new Date(sonGuncelleme).toLocaleTimeString("tr-TR", { hour: "2-digit", minute: "2-digit" })}
        </div>
      </div>

      {/* Mesajlar */}
      <div ref={messageContainerRef} style={{ flex: 1, overflowY: "auto", padding: 16, background: "var(--bg0)" }}>
        {konusma.mesajlar.length === 0 ? (
          <div style={{ textAlign: "center", padding: "40px 0", color: "var(--text3)" }}>
            <div style={{ fontSize: 40, marginBottom: 12 }}>💬</div>
            <div>İlk mesajınızı gönderin</div>
          </div>
        ) : (
          <>
            {/* Yazıyor Göstergesi */}
            {konusma.yaziyor && (
              <div style={{ display: "flex", alignItems: "center", gap: 8, padding: "12px 16px", background: "var(--bg1)", borderRadius: "var(--r)", marginBottom: 12, animation: "fadeIn 0.3s" }}>
                <div style={{ width: 16, height: 16, borderRadius: "50%", background: "var(--mavi)", display: "flex", alignItems: "center", justifyContent: "center", fontSize: 10, animation: "bounce 1.4s infinite ease-in-out both" }}>
                  <span style={{ animationDelay: "-0.32s" }}>•</span>
                  <span style={{ animationDelay: "-0.16s" }}>•</span>
                  <span>•</span>
                </div>
                <div style={{ fontSize: 13, color: "var(--text3)" }}>
                  {konusma.yaziyorAd || partnerAd} yazıyor...
                </div>
              </div>
            )}

            {/* Konuşma Temizlendı */}
            {konusmaBitti && (
              <div style={{ textAlign: "center", padding: "12px", fontSize: 13, color: "var(--text3)", background: "var(--bg1)", borderRadius: "var(--r)", marginBottom: 12, animation: "fadeIn 0.3s" }}>
                ✅ Mesajlar temizlendi
              </div>
            )}

            {/* Konuşma Açıldı Mesajı */}
            {konusmaAcildi && (
              <div style={{ textAlign: "center", padding: "8px", fontSize: 12, color: "var(--text3)", background: "var(--bg1)", borderRadius: "var(--r)", marginBottom: 8, animation: "fadeIn 0.3s" }}>
                🎉 Konuşma başladı
              </div>
            )}

            <div style={{ display: "flex", flexDirection: "column", gap: 12 }}>
            {konusma.mesajlar.map((m, i) => {
              const isBen = m.gonderen === "ben";
              return (
                <div key={m.id} style={{
                  maxWidth: "80%",
                  padding: "10px 14px",
                  borderRadius: "var(--r)",
                  fontSize: 14,
                  lineHeight: 1.5,
                  position: "relative",
                  alignSelf: isBen ? "flex-end" : "flex-start",
                  background: isBen ? "var(--mavi)" : "var(--bg3)",
                  color: isBen ? "#fff" : "var(--text2)",
                  animation: "fadeIn 0.3s ease"
                }}>
                  {m.veriTipi !== "metin" && m.veri && (
                    <div style={{
                      marginBottom: 8,
                      padding: "8px 12px",
                      background: "rgba(0,0,0,0.2)",
                      borderRadius: "8px",
                      border: "1px solid rgba(255,255,255,0.1)"
                    }}>
                      {m.veri.tip === "img" ? (
                        <img src={m.veri.veri} alt={m.veri.ad} style={{ maxWidth: 200, borderRadius: "6px", cursor: "pointer" }} />
                      ) : (
                        <div style={{ display: "flex", alignItems: "center", gap: 8 }}>
                          <span style={{ fontSize: 20 }}>📄</span>
                          <div>
                            <div style={{ fontWeight: 600 }}>{m.veri.ad}</div>
                            <div style={{ fontSize: 11, opacity: 0.8 }}>{(m.veri.boyut / 1024).toFixed(1)} KB</div>
                          </div>
                        </div>
                      )}
                      {m.metin && <div style={{ marginTop: 8, color: "rgba(255,255,255,0.8)" }}>{m.metin}</div>}
                    </div>
                  )}
                  {m.metin && (
                    <div>
                      {m.metin.split("\n").map((line, idx) => (
                        <div key={idx}>{line || <br />}</div>
                      ))}
                    </div>
                  )}
                  <div style={{
                    fontSize: 9,
                    marginTop: 4,
                    opacity: 0.6,
                    textAlign: isBen ? "right" : "left",
                    display: "flex",
                    alignItems: "center",
                    gap: 4
                  }}>
                    {new Date(m.zaman).toLocaleTimeString("tr-TR", { hour: "2-digit", minute: "2-digit" })}
                    {m.okunduZamani && !isBen && (
                      <span style={{ color: "#4ade80", fontSize: 10 }}> ✓</span>
                    )}
                    {isBen && (
                      <span style={{ color: "#94a3b8" }}>
                        {new Date(m.zaman).toLocaleTimeString("tr-TR", { hour: "2-digit", minute: "2-digit" })}
                      </span>
                    )}
                    <div style={{ flex: 1 }}></div>
                    <button
                      onClick={temizle}
                      style={{
                        background: "none",
                        border: "none",
                        cursor: "pointer",
                        opacity: 0.4,
                        fontSize: 12,
                        padding: "4px 8px",
                        borderRadius: "4px",
                        transition: "all 0.2s"
                      }}
                      title="Mesajları sil"
                    >
                      🗑️ Temizle
                    </button>
                  </div>
                </div>
              );
            })}
            </div>
          </>
        )}
      </div>

      {/* Input */}
      <div style={{ padding: 12, borderTop: "1px solid var(--border)", background: "var(--bg1)" }}>
        <form onSubmit={gonder} style={{ display: "flex", gap: 8, alignItems: "flex-end" }}>
          <label style={{ padding: 10, cursor: "pointer", background: "var(--bg2)", borderRadius: "var(--r)", fontSize: 20, transition: "all 0.2s" }} title="Dosya yükle">
            📎
            <input type="file" accept="image/*,.pdf" onChange={dosyaYukle} style={{ display: "none" }} />
          </label>

          <input
            className="input"
            placeholder="Mesaj yazın..."
            value={mesaj}
            onChange={e => setMesaj(e.target.value)}
            onKeyPress={e => e.key === "Enter" && gonder(e)}
            style={{ flex: 1, padding: "10px 14px" }}
          />

          <button
            type="submit"
            disabled={!mesaj.trim() && !dosya || yukleniyor}
            className="btn btn-primary"
            style={{
              padding: "10px 16px",
              background: (mesaj.trim() || dosya) && !yukleniyor ? "var(--mavi)" : "var(--bg3)",
              opacity: (mesaj.trim() || dosya) && !yukleniyor ? 1 : 0.5,
              cursor: (mesaj.trim() || dosya) && !yukleniyor ? "pointer" : "not-allowed",
              borderRadius: "var(--r)",
              fontSize: 18,
              display: "flex",
              alignItems: "center",
              justifyContent: "center"
            }}
            title={yukleniyor ? "Yükleniyor..." : "Gönder"}
          >
            {yukleniyor ? "⏳" : "➤"}
          </button>
        </form>
      </div>

      <style>{`
        @keyframes fadeIn {
          from { opacity: 0; transform: translateY(10px); }
          to { opacity: 1; transform: translateY(0); }
        }
      `}</style>
    </div>
  );
}
